public class SharedDivide
{
    public static int divide(int a, int b)
    {
        return a / b;
    }
    public static void reportApp()
    {
        try
        {
            System.out.print(divide(10, 0) + " ");
        }
        catch(ArithmeticException e)
        {
            System.out.print("N/A ");
        }
    }
    public static void safeApp()
    {
        int r;
        try
        {
            r = divide(10, 0);
        }
        catch(ArithmeticException e)
        {
            r = divide(10, 1);
        }
        System.out.print(r + " ");
    }
    public static void main(String[] args)
    {
        reportApp();
        safeApp();
        System.out.println();
    }
}

